func testPermissionToManyAddOpPermissionIdAccessControls(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Permission
	var b, c, d, e AccessControl

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, permissionDBTypes, false, strmangle.SetComplement(permissionPrimaryKeyColumns, permissionColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*AccessControl{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, accessControlDBTypes, false, strmangle.SetComplement(accessControlPrimaryKeyColumns, accessControlColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*AccessControl{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddPermissionIdAccessControls(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.ID != first.PermissionId {
			t.Error("foreign key was wrong value", a.ID, first.PermissionId)
		}
		if a.ID != second.PermissionId {
			t.Error("foreign key was wrong value", a.ID, second.PermissionId)
		}

		if first.R.PermissionIdPermission != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.PermissionIdPermission != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.PermissionIdAccessControls[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.PermissionIdAccessControls[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.PermissionIdAccessControls().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
