func testPermissionToManyRemoveOpRoleIdRoles(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Permission
	var b, c, d, e Role

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, permissionDBTypes, false, strmangle.SetComplement(permissionPrimaryKeyColumns, permissionColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Role{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, roleDBTypes, false, strmangle.SetComplement(rolePrimaryKeyColumns, roleColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddRoleIdRoles(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.RoleIdRoles().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveRoleIdRoles(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.RoleIdRoles().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if len(b.R.PermissionIdPermissions) != 0 {
		t.Error("relationship was not removed properly from the slice")
	}
	if len(c.R.PermissionIdPermissions) != 0 {
		t.Error("relationship was not removed properly from the slice")
	}
	if d.R.PermissionIdPermissions[0] != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.PermissionIdPermissions[0] != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if len(a.R.RoleIdRoles) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.RoleIdRoles[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.RoleIdRoles[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

func testPermissionToOneActionUsingActionIdAction(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Permission
	var foreign Action

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, permissionDBTypes, false, permissionColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Permission struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, actionDBTypes, false, actionColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Action struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.ActionId = foreign.ID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.ActionIdAction().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.ID != foreign.ID {
		t.Errorf("want: %v, got %v", foreign.ID, check.ID)
	}

	ranAfterSelectHook := false
	AddActionHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *Action) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := PermissionSlice{&local}
	if err = local.L.LoadActionIdAction(ctx, tx, false, (*[]*Permission)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.ActionIdAction == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.ActionIdAction = nil
	if err = local.L.LoadActionIdAction(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.ActionIdAction == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

